use anyhow :: { Context , Result } ; use std :: path :: { Path , PathBuf } ; use std :: fs ; use std :: process :: Command ; use std :: collections :: HashMap ; use toml_edit :: { Document , DocumentMut } ; use crate :: context :: AppContext ; use crate :: repo_collection :: { RepoIdentifier , collect_repo_info } ; use crate :: actions :: { RepoAction , create_actions_plan } ; use crate :: workspace :: { find_workspace_cargo_files , discover_all_git_repositories } ; use crate :: zkperf_integration :: ZkperfIntegrator ; use super :: * ; # [doc = " Enhanced workload vendoring that discovers ALL repositories (not just workspace members)"] pub fn vendor_workload (ctx : & AppContext , workspace_path : & PathBuf , fork_dir : & PathBuf , apply_zkperf : bool ,) -> Result < () > { println ! ("Starting enhanced workload vendoring...") ; println ! ("Workspace path: {}" , workspace_path . display ()) ; println ! ("Fork directory: {}" , fork_dir . display ()) ; if apply_zkperf { println ! ("Will apply zkperf annotations") ; } let cargo_files = find_workspace_cargo_files (workspace_path , true) ? ; println ! ("Found {} Cargo.toml files in project" , cargo_files . len ()) ; let git_repos = discover_all_git_repositories (workspace_path) ? ; println ! ("Found {} git repositories in project" , git_repos . len ()) ; let mut all_repo_info = HashMap :: new () ; for cargo_file in & cargo_files { if ctx . verbose { println ! ("Processing: {}" , cargo_file . display ()) ; } let mut temp_ctx = ctx . clone () ; temp_ctx . manifest_path = cargo_file . clone () ; temp_ctx . root_dir = cargo_file . parent () . unwrap () . to_path_buf () ; let repo_info = collect_repo_info (& temp_ctx) ? ; for (name , info) in repo_info { all_repo_info . insert (name , info) ; } } for git_repo in & git_repos { let repo_name = git_repo . file_name () . and_then (| n | n . to_str ()) . unwrap_or ("unknown") ; if ! all_repo_info . contains_key (repo_name) { println ! ("Adding git repository not found in Cargo.toml: {}" , repo_name) ; all_repo_info . insert (repo_name . to_string () , RepoIdentifier { url : format ! ("local://{}" , git_repo . display ()) , version : "0.0.0" . to_string () , commit : None , owner : "local" . to_string () , repo_name : repo_name . to_string () , }) ; } } println ! ("Collected {} unique git dependencies from project" , all_repo_info . len ()) ; create_local_forks (& all_repo_info , fork_dir , & ctx . git_executable_path) ? ; let actions_plan = create_actions_plan (ctx , & all_repo_info) ; do_workload_vendoring (ctx , actions_plan , fork_dir) ? ; if apply_zkperf { apply_zkperf_annotations_with_integrator (fork_dir , & ctx . git_executable_path) ? ; } create_workload_patches (ctx , fork_dir) ? ; println ! ("Enhanced workload vendoring completed successfully!") ; Ok (()) }